import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"Alipay Bill Import Guide","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/guide/03-alipay-bill-import-guide.md","filePath":"v1/en/guide/03-alipay-bill-import-guide.md"}'),l={name:"v1/en/guide/03-alipay-bill-import-guide.md"};function r(n,e,s,d,p,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="alipay-bill-import-guide" tabindex="-1">Alipay Bill Import Guide <a class="header-anchor" href="#alipay-bill-import-guide" aria-label="Permalink to &quot;Alipay Bill Import Guide&quot;">​</a></h1><h2 id="📋-overview" tabindex="-1">📋 Overview <a class="header-anchor" href="#📋-overview" aria-label="Permalink to &quot;📋 Overview&quot;">​</a></h2><p>This guide shows you how to export bills from Alipay and import them into Expense Tracker: Koala (“Koala”).</p><hr><h2 id="📱-part-1-export-bills-in-alipay" tabindex="-1">📱 Part 1: Export bills in Alipay <a class="header-anchor" href="#📱-part-1-export-bills-in-alipay" aria-label="Permalink to &quot;📱 Part 1: Export bills in Alipay&quot;">​</a></h2><h3 id="step-1-open-the-bills-page" tabindex="-1">Step 1: Open the Bills page <a class="header-anchor" href="#step-1-open-the-bills-page" aria-label="Permalink to &quot;Step 1: Open the Bills page&quot;">​</a></h3><ol><li>Open Alipay</li><li>Tap <strong>Me</strong></li><li>Tap <strong>Bills</strong></li></ol><blockquote><p>📝 Note: Entry points may vary by Alipay version. If you can’t find it, try searching “账单” in Alipay.</p></blockquote><h3 id="step-2-start-export" tabindex="-1">Step 2: Start export <a class="header-anchor" href="#step-2-start-export" aria-label="Permalink to &quot;Step 2: Start export&quot;">​</a></h3><ol><li>On the Bills page, tap <strong>...</strong> (top-right)</li><li>Select <strong>Transaction statement</strong> / <strong>Bill export</strong> (wording may differ)</li><li>Choose <strong>Personal reconciliation</strong> and tap <strong>Apply</strong></li></ol><h3 id="step-3-select-export-options" tabindex="-1">Step 3: Select export options <a class="header-anchor" href="#step-3-select-export-options" aria-label="Permalink to &quot;Step 3: Select export options&quot;">​</a></h3><ol><li>Choose transaction type: <strong>All</strong> / <strong>Income</strong> / <strong>Expense</strong></li><li>Choose the time range (e.g. last month / last 3 months)</li><li>Choose delivery method: <strong>Alipay</strong> / <strong>Email</strong></li></ol><blockquote><p>💡 Tips:</p><ul><li>Export up to 3 months at a time to avoid very large files.</li><li>For longer history, export multiple files.</li><li>If you choose email, Alipay sends the file as an attachment (make sure your email is configured).</li></ul></blockquote><h3 id="step-4-save-the-file-to-your-device" tabindex="-1">Step 4: Save the file to your device <a class="header-anchor" href="#step-4-save-the-file-to-your-device" aria-label="Permalink to &quot;Step 4: Save the file to your device&quot;">​</a></h3><ol><li>If delivered via email: <ul><li>Open your mailbox and find the message from Alipay</li><li>Download the attachment (CSV)</li><li>Save it locally (so the file picker can access it)</li></ul></li><li>If “Save to Files” is available: <ul><li>Save it to your Downloads folder</li><li>Remember the location</li></ul></li></ol><blockquote><p>📝 Where the file usually goes:</p><ul><li>iOS: Files app → Downloads</li><li>Android: Downloads folder or Alipay folder</li></ul></blockquote><hr><h2 id="📱-part-2-import-into-expense-tracker-koala" tabindex="-1">📱 Part 2: Import into Expense Tracker: Koala <a class="header-anchor" href="#📱-part-2-import-into-expense-tracker-koala" aria-label="Permalink to &quot;📱 Part 2: Import into Expense Tracker: Koala&quot;">​</a></h2><h3 id="step-1-open-the-import-page" tabindex="-1">Step 1: Open the import page <a class="header-anchor" href="#step-1-open-the-import-page" aria-label="Permalink to &quot;Step 1: Open the import page&quot;">​</a></h3><ol><li>Open Expense Tracker: Koala</li><li>Tap <strong>Settings</strong></li><li>Find <strong>Bill Import</strong></li><li>Enter the bill import page</li></ol><h3 id="step-2-choose-the-import-source" tabindex="-1">Step 2: Choose the import source <a class="header-anchor" href="#step-2-choose-the-import-source" aria-label="Permalink to &quot;Step 2: Choose the import source&quot;">​</a></h3><ol><li>Tap <strong>Import source</strong></li><li>Select <strong>Alipay</strong></li></ol><blockquote><p>⚠️ Important: You must choose <strong>Alipay</strong>, otherwise the file cannot be parsed correctly.</p></blockquote><h3 id="step-3-pick-the-file" tabindex="-1">Step 3: Pick the file <a class="header-anchor" href="#step-3-pick-the-file" aria-label="Permalink to &quot;Step 3: Pick the file&quot;">​</a></h3><ol><li>Tap <strong>File path</strong></li><li>Select the CSV file exported from Alipay</li><li>Confirm the file name is shown</li></ol><h3 id="step-4-link-a-ledger" tabindex="-1">Step 4: Link a ledger <a class="header-anchor" href="#step-4-link-a-ledger" aria-label="Permalink to &quot;Step 4: Link a ledger&quot;">​</a></h3><ol><li>Tap <strong>Linked ledger</strong></li><li>Choose the target ledger</li></ol><blockquote><p>💡 Tip: If you only have one ledger, Koala links it automatically.</p></blockquote><h3 id="step-5-parse-preview-and-import" tabindex="-1">Step 5: Parse, preview, and import <a class="header-anchor" href="#step-5-parse-preview-and-import" aria-label="Permalink to &quot;Step 5: Parse, preview, and import&quot;">​</a></h3><ol><li>Tap <strong>Parse</strong> (top-right)</li><li>Review records on the preview page</li><li>Edit categories/accounts/notes if needed</li><li>Tap <strong>Import</strong></li></ol><hr><h2 id="📋-alipay-csv-columns-reference" tabindex="-1">📋 Alipay CSV columns (reference) <a class="header-anchor" href="#📋-alipay-csv-columns-reference" aria-label="Permalink to &quot;📋 Alipay CSV columns (reference)&quot;">​</a></h2><p>Alipay’s CSV export typically contains:</p><table tabindex="0"><thead><tr><th>Column name (as exported)</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>交易时间</td><td>Transaction time</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分类</td><td>Category label</td><td>餐饮美食/日用百货</td></tr><tr><td>交易对方</td><td>Counterparty</td><td>张三 / Merchant name</td></tr><tr><td>对方账号</td><td>Counterparty account</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品说明</td><td>Item description</td><td>Lunch / Shopping</td></tr><tr><td>收/支</td><td>Income / Expense</td><td>收入 / 支出</td></tr><tr><td>金额</td><td>Amount</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>Payment method/account</td><td>余额宝</td></tr><tr><td>交易状态</td><td>Status</td><td>交易成功 / 已退款</td></tr><tr><td>交易订单号</td><td>Transaction order no.</td><td>20240101...</td></tr><tr><td>商家订单号</td><td>Merchant order no.</td><td>1234567890</td></tr><tr><td>备注</td><td>Note</td><td>备注内容</td></tr></tbody></table><blockquote><p>📝 Note: Column names may vary slightly by Alipay version, but the meaning is the same.</p></blockquote><hr><h2 id="⚠️-notes" tabindex="-1">⚠️ Notes <a class="header-anchor" href="#⚠️-notes" aria-label="Permalink to &quot;⚠️ Notes&quot;">​</a></h2><h3 id="_1-file-requirements" tabindex="-1">1. File requirements <a class="header-anchor" href="#_1-file-requirements" aria-label="Permalink to &quot;1. File requirements&quot;">​</a></h3><ul><li><strong>Encoding</strong>: UTF-8 is recommended (Alipay exports may be UTF-8 or GBK)</li><li><strong>Format</strong>: CSV only (<code>.csv</code>)</li><li><strong>Size</strong>: recommended under 10MB per file</li></ul><h3 id="_2-field-mapping-how-koala-imports" tabindex="-1">2. Field mapping (how Koala imports) <a class="header-anchor" href="#_2-field-mapping-how-koala-imports" aria-label="Permalink to &quot;2. Field mapping (how Koala imports)&quot;">​</a></h3><p>Koala maps Alipay columns to Koala fields automatically:</p><ul><li>Transaction time (row[0]) → bill date (date only, <code>yyyy-MM-dd</code>)</li><li>Category (row[1]) → category (parent and child set to the same name)</li><li>Counterparty / account / item / status / order numbers → appended into the bill note (combined)</li><li>Income/expense (row[5]) → bill type (income/expense)</li><li>Amount (row[6]) → bill amount</li><li>Payment method (row[7]) → account (matched by name; created if missing)</li><li>Note (row[11]) → bill note (used as the original note; “/” or empty is ignored, then Koala appends extra lines)</li></ul><h3 id="_3-category-and-account-matching" tabindex="-1">3. Category and account matching <a class="header-anchor" href="#_3-category-and-account-matching" aria-label="Permalink to &quot;3. Category and account matching&quot;">​</a></h3><ul><li>Automatic matching may not be perfect; review and adjust in the preview page.</li><li>If an account does not exist, Koala may create it automatically.</li></ul><h3 id="_4-duplicate-and-refund-handling" tabindex="-1">4. Duplicate and refund handling <a class="header-anchor" href="#_4-duplicate-and-refund-handling" aria-label="Permalink to &quot;4. Duplicate and refund handling&quot;">​</a></h3><ul><li>If a record is detected as a duplicate (based on transaction identifiers), Koala may skip it.</li><li>Refund-related records are usually marked as “已退款/退款成功”; review them in the preview page.</li></ul><h3 id="_5-avoid-manual-edits-to-the-export-file" tabindex="-1">5. Avoid manual edits to the export file <a class="header-anchor" href="#_5-avoid-manual-edits-to-the-export-file" aria-label="Permalink to &quot;5. Avoid manual edits to the export file&quot;">​</a></h3><p>Do not modify the exported file (especially headers/columns). Renaming headers, deleting columns, or adding columns may cause parsing to fail.</p><hr><h2 id="🔧-faq" tabindex="-1">🔧 FAQ <a class="header-anchor" href="#🔧-faq" aria-label="Permalink to &quot;🔧 FAQ&quot;">​</a></h2><h3 id="q1-i-can-t-find-bill-export" tabindex="-1">Q1: I can’t find “Bill export”. <a class="header-anchor" href="#q1-i-can-t-find-bill-export" aria-label="Permalink to &quot;Q1: I can’t find “Bill export”.&quot;">​</a></h3><p>Possible reasons:</p><ol><li>Your Alipay version is too old</li><li>The entry point is different</li></ol><p>Try:</p><ul><li>Tap <strong>...</strong> on the Bills page</li><li>Look for <strong>Bills</strong> under Me</li><li>Search “账单导出” in Alipay</li></ul><h3 id="q2-i-didn-t-receive-the-email" tabindex="-1">Q2: I didn’t receive the email. <a class="header-anchor" href="#q2-i-didn-t-receive-the-email" aria-label="Permalink to &quot;Q2: I didn’t receive the email.&quot;">​</a></h3><p>Check:</p><ol><li>Whether an email address is linked in Alipay</li><li>Whether the email address is correct</li><li>Spam/junk folder</li><li>Try “Save to Files” (if available)</li></ol><h3 id="q3-parsing-failed" tabindex="-1">Q3: Parsing failed. <a class="header-anchor" href="#q3-parsing-failed" aria-label="Permalink to &quot;Q3: Parsing failed.&quot;">​</a></h3><p>Check:</p><ol><li>File format is CSV</li><li>Import source is set to Alipay</li><li>File is not corrupted</li><li>Encoding is correct (UTF-8 or GBK)</li></ol><h3 id="q4-categories-look-wrong-after-import" tabindex="-1">Q4: Categories look wrong after import. <a class="header-anchor" href="#q4-categories-look-wrong-after-import" aria-label="Permalink to &quot;Q4: Categories look wrong after import.&quot;">​</a></h3><p>This can happen because Alipay’s category labels may not match Koala’s categories exactly. Review and adjust categories in the preview page, or batch-edit after import.</p><h3 id="q5-can-i-import-images" tabindex="-1">Q5: Can I import images? <a class="header-anchor" href="#q5-can-i-import-images" aria-label="Permalink to &quot;Q5: Can I import images?&quot;">​</a></h3><p>Not supported.</p><h3 id="q6-how-much-history-can-i-import" tabindex="-1">Q6: How much history can I import? <a class="header-anchor" href="#q6-how-much-history-can-i-import" aria-label="Permalink to &quot;Q6: How much history can I import?&quot;">​</a></h3><p>There is no strict limit, but it’s recommended to:</p><ol><li>Import up to 3 months per file</li><li>Split large ranges into multiple files</li><li>Keep the app in the foreground during import</li></ol><h3 id="q7-why-is-only-csv-supported" tabindex="-1">Q7: Why is only CSV supported? <a class="header-anchor" href="#q7-why-is-only-csv-supported" aria-label="Permalink to &quot;Q7: Why is only CSV supported?&quot;">​</a></h3><p>Alipay currently exports bills in CSV. If Excel export becomes available, the guide will be updated.</p><hr><h2 id="💡-tips" tabindex="-1">💡 Tips <a class="header-anchor" href="#💡-tips" aria-label="Permalink to &quot;💡 Tips&quot;">​</a></h2><ol><li>Import regularly (e.g. monthly) to keep data up to date</li><li>Review categories after import for better statistics</li><li>Create common accounts ahead of time to avoid messy auto-created names</li><li>Consider backing up your data before importing</li><li>Review refund records after import</li></ol><hr><p><strong>Last updated</strong>: May 2026</p>',75)])])}const u=t(l,[["render",r]]);export{m as __pageData,u as default};
